// Procedural art: all materials are generated locally; no external assets or requests.
export function decorateHouse({THREE,scene,materials,box,sphere,rod,glow}){
 let seed=3187;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
 function texture(draw,repeatX=1,repeatY=1){let c=document.createElement('canvas');c.width=c.height=512;let ctx=c.getContext('2d');draw(ctx);let t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(repeatX,repeatY);t.anisotropy=4;return t;}
 const wood=texture(ctx=>{ctx.fillStyle='#76573c';ctx.fillRect(0,0,512,512);for(let y=0;y<512;y+=64){ctx.fillStyle=`hsl(29 25% ${27+random()*12}%)`;ctx.fillRect(0,y,512,63);ctx.fillStyle='#251e18';ctx.fillRect(0,y,512,2);for(let i=0;i<140;i++){ctx.strokeStyle=`rgba(${random()>.5?'222,179,120':'25,17,11'},${random()*.16})`;ctx.beginPath();let yy=y+random()*62;ctx.moveTo(0,yy);ctx.bezierCurveTo(150,yy+random()*8,350,yy-random()*8,512,yy);ctx.stroke();}for(let x=(y%128?70:210);x<512;x+=255){ctx.fillStyle='#27201a';ctx.fillRect(x,y,2,64);ctx.fillRect(x+6,y+8,3,3);ctx.fillRect(x+6,y+52,3,3);}}},5,6);
 const wallpaper=texture(ctx=>{ctx.fillStyle='#64716b';ctx.fillRect(0,0,512,512);for(let x=0;x<512;x+=64){ctx.fillStyle='#b9ae7613';ctx.fillRect(x,0,2,512);for(let y=0;y<512;y+=64){ctx.strokeStyle='#c8bf8d35';ctx.beginPath();ctx.moveTo(x+32,y+8);ctx.quadraticCurveTo(x+52,y+32,x+32,y+56);ctx.quadraticCurveTo(x+12,y+32,x+32,y+8);ctx.stroke();ctx.fillStyle='#bbb68c40';ctx.beginPath();ctx.arc(x+32,y+32,3,0,7);ctx.fill();}}for(let i=0;i<2400;i++){ctx.fillStyle=`rgba(10,17,15,${random()*.08})`;ctx.fillRect(random()*512,random()*512,1+random()*4,1+random()*14);}let g=ctx.createLinearGradient(0,0,0,512);g.addColorStop(0,'#121d2633');g.addColorStop(.7,'#0000');g.addColorStop(1,'#100e0c99');ctx.fillStyle=g;ctx.fillRect(0,0,512,512);},2,1);
 const fabric=texture(ctx=>{ctx.fillStyle='#582f28';ctx.fillRect(0,0,512,512);for(let x=0;x<512;x+=4){ctx.fillStyle='#e7bb7410';ctx.fillRect(x,0,1,512);ctx.fillRect(0,x,512,1);}for(let i=0;i<5;i++){ctx.strokeStyle=i%2?'#ae8258':'#282e28';ctx.lineWidth=3;ctx.strokeRect(16+i*9,16+i*9,480-i*18,480-i*18);}for(let y=100;y<430;y+=64){ctx.strokeStyle='#b17c4744';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(256,y-28);ctx.lineTo(290,y);ctx.lineTo(256,y+28);ctx.lineTo(222,y);ctx.closePath();ctx.stroke();}},1,7);
 for(const m of Object.values(materials)){let hex=m.color.getHex();if(hex===0x342e29){m.map=wood;m.color.setHex(0xc7b299);}else if([0x3c4647,0x344046,0x46504f,0x424947].includes(hex)){m.map=wallpaper;m.color.setHex(0xbac2b6);}else if([0x443328,0x72513b,0x403225,0x5d4936,0x57422e,0x9d744c].includes(hex)){let t=wood.clone();t.repeat.set(1,1);m.map=t;m.color.setHex(0xc1a98b);}else if(hex===0x59302b){m.map=fabric;m.color.setHex(0xe2c7b2);}m.needsUpdate=true;}
 // Doorways, wainscoting, crown molding and hallway sconces make a readable house.
 for(const x of [-3,3]){
  for(const [z,width] of [[-9,2],[0,4],[9,2]]){
   for(let side of [-1,1]){box(.42,3.05,.15,0x57422e,x,1.53,z+side*(width/2));box(.5,.2,.24,0x846a4a,x,.12,z+side*(width/2));}
   box(.44,.22,width+.25,0x57422e,x,3.04,z);
  }
  for(const [z,len]of [[-12,4],[-5,6],[5,6],[12,4]]){for(let s of [-1,1]){box(.04,.8,len,0x363d36,x+s*.15,.42,z);box(.07,.07,len,0x877458,x+s*.18,.87,z);box(.11,.13,len,0x57422e,x+s*.18,.09,z);box(.11,.16,len,0x57422e,x+s*.18,3.33,z);for(let zz=z-len/2+.5;zz<z+len/2;zz+=.9)box(.04,.58,.035,0x847156,x+s*.18,.44,zz);}}
 }
 const candleMat=new THREE.MeshStandardMaterial({color:0xffc476,emissive:0xff9d31,emissiveIntensity:2.5});
 for(const [x,z]of [[-2.7,3],[2.7,-3],[-2.7,-6],[2.7,6]]){box(.08,.45,.25,0x392f27,x,2.1,z);box(.34,.04,.25,0xb99357,x,1.95,z);box(.10,.28,.10,0xd7c3a4,x,2.1,z);sphere(.07,candleMat,x,2.3,z,scene,.65,1.6,.65);}
 for(const side of [-1,1])for(const z of [-9,0,9]){const x=side*12.57;for(const zz of [z-1.35,z+1.35]){box(.17,2.3,.18,0x7a6042,x,2,zz);for(let i=0;i<5;i++)box(.1,2.25,.08,0x383d3a,x-side*.08,2,zz+(i-2)*.12);}box(.25,.18,2.9,0x58442f,x,3.18,z);box(.3,.12,2.85,0x665640,x,1.13,z);}
 function picture(x,z,rotation,variant){let g=new THREE.Group();scene.add(g);g.position.set(x,2,z);g.rotation.y=rotation;box(1.75,1.2,.09,0x332c23,0,0,0,g);box(1.56,1.02,.1,0xa78551,0,0,.012,g);let t=texture(ctx=>{let grad=ctx.createLinearGradient(0,0,0,512);grad.addColorStop(0,variant?'#29323b':'#384550');grad.addColorStop(1,'#9b8161');ctx.fillStyle=grad;ctx.fillRect(0,0,512,512);ctx.fillStyle='#d5bb85';ctx.beginPath();ctx.arc(345,135,38,0,7);ctx.fill();for(let i=0;i<3;i++){ctx.fillStyle=['#656357','#414b44','#252f2e'][i];ctx.beginPath();ctx.moveTo(0,512);for(let x=0;x<520;x+=20)ctx.lineTo(x,260+i*65+Math.sin(x*.015+i)*60);ctx.lineTo(512,512);ctx.fill();}for(let i=0;i<15;i++){let x=random()*512,y=350+random()*150;ctx.fillStyle='#182625';ctx.beginPath();ctx.moveTo(x,y-100);ctx.lineTo(x-25,y);ctx.lineTo(x+25,y);ctx.fill();}});let p=new THREE.Mesh(new THREE.PlaneGeometry(1.43,.89),new THREE.MeshStandardMaterial({map:t,roughness:.85}));p.position.z=.07;g.add(p);}
 picture(-6,4.35,0,0);picture(7,-4.35,0,1);picture(-6,-4.35,0,1);picture(6,4.65,0,0);
 // Fireplace, logs and animated fire in the living room.
 box(2.6,1.7,.65,0x514e47,10, .85,3.95);box(1.65,1.15,.08,0x141514,10,.65,3.58);box(2.85,.18,.9,0x8e8271,10,1.8,3.95);box(2.8,.15,1.1,0x696354,10,.08,3.7);
 for(let i=0;i<3;i++){let log=box(.16,.15,1.2,0x32251b,9.65+i*.34,.25,3.6);log.rotation.y=1.2+i*.3;}
 const flames=[];for(let i=0;i<6;i++){let m=new THREE.Mesh(new THREE.ConeGeometry(.12+random()*.08,.4+random()*.2,5),new THREE.MeshBasicMaterial({color:i%2?0xffa52c:0xff6323,transparent:true,opacity:.8}));m.position.set(9.5+i*.2,.5,3.5);m.userData.dynamic=true;scene.add(m);flames.push(m);}let fire=glow(0xff853b,3,7,10,.9,3.2);
 // Kitchen sink, tap, stove, cupboards and dishes.
 box(1.15,.05,.85,0x353f42,8.1,1.035,12.6);box(.85,.03,.6,0x19262a,8.1,1.07,12.6);rod(new THREE.Vector3(8.1,1.05,13),new THREE.Vector3(8.1,1.5,13),.035,0xaab1ac);rod(new THREE.Vector3(8.1,1.5,13),new THREE.Vector3(8.1,1.5,12.65),.035,0xaab1ac);
 box(1.1,.07,1.2,0x444b4b,10.6,1.06,12.7);for(let x of [10.3,10.9])for(let z of [12.4,13]){let ring=new THREE.Mesh(new THREE.TorusGeometry(.18,.025,6,16),new THREE.MeshStandardMaterial({color:0x181c1c,metalness:.6}));ring.rotation.x=Math.PI/2;ring.position.set(x,1.11,z);scene.add(ring);}
 for(let x=7;x<11;x+=1.05){box(.95,.7,.09,0x5d4936,x,.5,11.95);box(.3,.045,.07,0xb2a17a,x,.66,11.87);box(.95,.85,.6,0x4c5a52,x,2.45,13.35);box(.07,.25,.08,0xb2a17a,x+.3,2.45,12.99);}
 for(let i=0;i<3;i++){let plate=new THREE.Mesh(new THREE.CylinderGeometry(.23,.2,.035,20),new THREE.MeshStandardMaterial({color:0xc9c4ac}));plate.position.set(7.1,1.02+i*.035,7.2);scene.add(plate);}
 // A grandfather clock with a moving pendulum in the dining room.
 box(.9,2.9,.5,0x5d4936,-11.9,1.45,-3.4);box(.64,1.3,.06,0x1b2629,-11.9,1.2,-3.11);const pendulum=new THREE.Group();pendulum.position.set(-11.9,1.8,-3.04);scene.add(pendulum);rod(new THREE.Vector3(),new THREE.Vector3(0,-1,0),.016,0xaf9967,pendulum);sphere(.13,0xb1a06c,0,-1,0,pendulum);
 let clock=texture(ctx=>{ctx.fillStyle='#d2c5a1';ctx.fillRect(0,0,512,512);ctx.strokeStyle='#44392c';ctx.lineWidth=14;ctx.beginPath();ctx.arc(256,256,235,0,7);ctx.stroke();ctx.fillStyle='#42362c';ctx.font='bold 42px serif';ctx.textAlign='center';for(let i=1;i<=12;i++){let a=i*Math.PI/6;ctx.fillText(i,256+Math.sin(a)*185,270-Math.cos(a)*185);}ctx.strokeStyle='#302d27';ctx.lineWidth=12;ctx.beginPath();ctx.moveTo(256,256);ctx.lineTo(256,117);ctx.moveTo(256,256);ctx.lineTo(350,295);ctx.stroke();});let dial=new THREE.Mesh(new THREE.PlaneGeometry(.72,.72),new THREE.MeshStandardMaterial({map:clock}));dial.position.set(-11.9,2.36,-3.1);scene.add(dial);
 // Small household details: a suitcase, workshop pegboard and scattered paper.
 box(1.1,.4,.7,0x655340,-6.7,.25,12);for(const x of [-7.05,-6.35])box(.08,.42,.72,0x2a2b27,x,.25,12);box(.4,.09,.1,0xb2a17a,-6.7,.5,12);
 box(2.6,1.2,.08,0x735d3c,8.6,2.05,-13.45);for(let x=7.5;x<10;x+=.25)for(let y=1.6;y<2.6;y+=.22)sphere(.018,0x2f3027,x,y,-13.39);for(let x of [8,8.6,9.2]){box(.05,.5,.05,0x4c4b42,x,2,-13.3);box(.24,.1,.1,0x888a7c,x,2.2,-13.3);}
 for(const [x,z]of [[-7.2,-1.5],[5.7,10.3],[1.1,-5.5],[-6,5.5]]){let p=box(.3,.006,.4,0xb5aa8c,x,.02,z);p.rotation.y=random()*2;}
 return dt=>{pendulum.rotation.z=Math.sin(dt*1.8)*.14;fire.intensity=2.6+Math.sin(dt*13)*.4;for(let i=0;i<flames.length;i++){flames[i].scale.y=.75+Math.sin(dt*11+i*2)*.2;flames[i].rotation.y=dt*.7+i;}};
}
// Merge immutable root meshes by material, reducing hundreds of draw calls.
export function batchStatic(THREE,scene,exclude){
 scene.updateMatrixWorld(true);let groups=new Map();for(const m of [...scene.children]){if(!m.isMesh||exclude.has(m)||m.userData.dynamic||Array.isArray(m.material))continue;let list=groups.get(m.material)||[];list.push(m);groups.set(m.material,list);}
 for(const [material,meshes]of groups){if(meshes.length<3)continue;let parts=meshes.map(m=>{let g=m.geometry.index?m.geometry.toNonIndexed():m.geometry.clone();g.applyMatrix4(m.matrixWorld);return g;});let geometry=new THREE.BufferGeometry();for(let name of ['position','normal','uv']){if(!parts.every(g=>g.attributes[name]))continue;let size=parts[0].attributes[name].itemSize,length=parts.reduce((n,g)=>n+g.attributes[name].array.length,0),out=new Float32Array(length),offset=0;for(let p of parts){out.set(p.attributes[name].array,offset);offset+=p.attributes[name].array.length;}geometry.setAttribute(name,new THREE.BufferAttribute(out,size));}geometry.computeBoundingSphere();let merged=new THREE.Mesh(geometry,material);merged.castShadow=merged.receiveShadow=true;scene.add(merged);meshes.forEach(m=>scene.remove(m));parts.forEach(p=>p.dispose());}
}
